parameters.jsCode:
const d = $input.item.json;
const phone = (d.phone || d.billing_address?.phone || '').replace(/\D/g, '');
const intlPhone = phone.startsWith('54') ? phone : '54' + phone.replace(/^0/, '');
const nombre = d.billing_address?.first_name || 'Cliente';
const productos = (d.line_items || []).map(i => `• ${i.quantity}x ${i.name}`).join('\n');
const total = parseFloat(d.total_price || 0).toLocaleString('es-AR');
const orden = d.order_number;
return [{ json: { phone: intlPhone, nombre, productos, total, orden } }];

